#!/usr/bin/env node
/**
 * scripts/verify-field-names.cjs
 * -------------------------------
 * CI enforcement: every Mongo field name this app's API routes reference
 * must be an exact, byte-for-byte match to a real field name currently
 * present in MongoDB — not "probably matches", verified against
 * field_registry.json (a live-scan ground truth generated by
 * ~/import's scripts/export_field_registry.py, copied into this repo).
 *
 * Built after a real incident: field_mapping.py's rename of
 * "Désignation Consomation " (trailing space) -> designation_consommation
 * silently never matched the real Mongo key, so this app's DS History
 * route queried a field that never existed and got null back with no
 * error. This script exists to make that class of bug fail loudly in CI
 * instead of shipping silently.
 *
 * Scope (documented limitation, not exhaustive): scans app/api/** for
 * quoted dollar-prefixed field references -- "$fieldname" -- the pattern
 * used throughout this codebase's aggregation pipelines ($project,
 * $group, $ifNull, etc). It does not attempt to parse bare object-key
 * field references (e.g. `{ immatriculation: imm }` in a $match) via a
 * full TS/AST walk, since those are indistinguishable from arbitrary JS
 * object keys without real type information. Extend this if a future
 * bug slips through that pattern.
 *
 * Collection scoping is per-file: every collection name passed to
 * getCollection(...) OR to a $lookup's `from:` anywhere in a file is
 * unioned into that file's allowed field set. This repo's field names
 * don't collide across collections in a way that would hide a real
 * mismatch (verified during the audit that introduced this script), so
 * file-level scoping is a deliberate simplicity/precision tradeoff, not
 * an oversight.
 *
 * Pipeline-local fields (e.g. `$addFields: { pu_numeric: {...} }` later
 * read back as "$pu_numeric") are never raw Mongo fields and must not be
 * checked against the registry -- they're computed within the pipeline
 * itself. Any object key of the form `name: "$..."`, `name: { $op: ...
 * }`, `name: 1`, or `name: 0` is treated as such a local definition and
 * excluded.
 *
 * Suppressing a known, temporary, documented exception (e.g. a dual-read
 * during a backfill window): add a same-file marker comment
 *   // verify-field-names:allow <fieldname> -- <reason>
 * Every allow marker is echoed in the pass output so temporary exceptions
 * stay visible instead of silently living forever.
 *
 * Plain CommonJS on purpose, not TypeScript -- runs with the system
 * `node` binary, no extra devDependency (tsx/ts-node) needed just to
 * run a CI lint script.
 *
 * Usage: pnpm verify-field-names
 */

const fs = require("node:fs");
const path = require("node:path");

const REPO_ROOT = path.join(__dirname, "..");
const REGISTRY_PATH = path.join(REPO_ROOT, "field_registry.json");
const SCAN_ROOT = path.join(REPO_ROOT, "app", "api");

function walk(dir, out = []) {
  for (const entry of fs.readdirSync(dir)) {
    const full = path.join(dir, entry);
    const st = fs.statSync(full);
    if (st.isDirectory()) {
      walk(full, out);
    } else if (/\.(ts|tsx)$/.test(entry) && !entry.includes(".test.")) {
      out.push(full);
    }
  }
  return out;
}

function main() {
  const registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, "utf8"));
  const files = walk(SCAN_ROOT);

  const GETCOLLECTION_RE = /getCollection\(\s*["'`](\w+)["'`]\s*\)/g;
  const LOOKUP_FROM_RE = /from:\s*["'`](\w+)["'`]/g;
  // Captures the name after a single leading "$", rejecting "$$..." (let
  // vars like $$ROOT/$$imm) via the negative lookahead.
  const FIELD_REF_RE = /["'`]\$(?!\$)([A-Za-zÀ-ÿ_][A-Za-zÀ-ÿ0-9_ ]*)["'`]/g;
  // Pipeline-local field definitions: `name: { $op: ... }` (always a
  // synthesized value -- $first/$push/$convert/etc) or `name: "$other"`
  // where `name !== other` (a rename/alias). Deliberately NOT matching
  // straight passthroughs like `foo: "$foo"` -- those are a direct read
  // of raw field `foo` and must still be checked against the registry;
  // treating them as "local" would silently exempt the single most
  // common case (a plain field read) from ever being verified.
  const LOCAL_FIELD_COMPUTED_RE = /["'`]?([A-Za-zÀ-ÿ_][A-Za-zÀ-ÿ0-9_]*)["'`]?\s*:\s*\{\s*\$/g;
  const LOCAL_FIELD_ALIAS_RE = /["'`]?([A-Za-zÀ-ÿ_][A-Za-zÀ-ÿ0-9_]*)["'`]?\s*:\s*["'`]\$([A-Za-zÀ-ÿ_][A-Za-zÀ-ÿ0-9_ ]*)["'`]/g;
  const ALLOW_RE = /verify-field-names:allow\s+(\S+)/g;

  const errors = [];
  const allowedNoted = [];

  for (const file of files) {
    const rel = path.relative(REPO_ROOT, file);
    const src = fs.readFileSync(file, "utf8");

    const collectionsInFile = new Set();
    for (const m of src.matchAll(GETCOLLECTION_RE)) {
      if (registry.collections[m[1]]) collectionsInFile.add(m[1]);
    }
    for (const m of src.matchAll(LOOKUP_FROM_RE)) {
      if (registry.collections[m[1]]) collectionsInFile.add(m[1]);
    }
    if (collectionsInFile.size === 0) continue; // file doesn't touch Mongo

    const allowed = new Set();
    for (const c of collectionsInFile) {
      for (const f of registry.collections[c]) allowed.add(f);
    }
    for (const m of src.matchAll(LOCAL_FIELD_COMPUTED_RE)) allowed.add(m[1]);
    for (const m of src.matchAll(LOCAL_FIELD_ALIAS_RE)) {
      if (m[1] !== m[2]) allowed.add(m[1]);
    }

    const fileAllowMarkers = new Set();
    for (const m of src.matchAll(ALLOW_RE)) {
      fileAllowMarkers.add(m[1]);
      allowedNoted.push(`${rel}: ${m[1]}`);
    }

    for (const m of src.matchAll(FIELD_REF_RE)) {
      const field = m[1];
      if (allowed.has(field) || fileAllowMarkers.has(field)) continue;

      const line = src.slice(0, m.index).split("\n").length;
      errors.push(
        `${rel}:${line}  "$${field}" — not in field_registry.json for {${[...collectionsInFile].join(", ")}}`
      );
    }
  }

  if (allowedNoted.length > 0) {
    console.log("Suppressed (documented) exceptions:");
    for (const a of allowedNoted) console.log(`  ${a}`);
    console.log();
  }

  if (errors.length > 0) {
    console.error(`✗ verify-field-names: ${errors.length} field reference(s) don't match field_registry.json:\n`);
    for (const e of errors) console.error(`  ${e}`);
    console.error(
      "\nEach of these references a field name that does not exist byte-for-byte in the live " +
      "MongoDB scan (field_registry.json). Either fix the reference, or if this is a deliberate " +
      "temporary exception (e.g. a dual-read during a backfill window), add a same-file comment:\n" +
      "  // verify-field-names:allow <fieldname> -- <reason>"
    );
    process.exit(1);
  }

  console.log(`✓ verify-field-names: all field references across ${files.length} scanned file(s) match field_registry.json`);
}

main();
